import random
from collections import deque

def solve_optimal(coins, amount):
    inf = amount + 1
    best = [0] + [inf] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and best[a - c] + 1 < best[a]:
                best[a] = best[a - c] + 1
    return best[amount] if best[amount] != inf else -1

def solve_brute(coins, amount):
    seen = {0}
    queue = deque([(0, 0)])
    while queue:
        total, used = queue.popleft()
        if total == amount:
            return used
        for c in coins:
            nxt = total + c
            if nxt <= amount and nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, used + 1))
    return -1

def gen(rng, size):
    count = rng.randint(1, {"tiny": 2, "small": 4, "large": 5}[size])
    top = {"tiny": 6, "small": 9, "large": 12}[size]
    coins = [rng.randint(1, top) for _ in range(count)]
    amount = rng.randint(0, {"tiny": 10, "small": 25, "large": 60}[size])
    return [coins, amount]

def validate(args):
    coins, amount = args
    return 1 <= len(coins) <= 12 and all(c >= 1 for c in coins) and 0 <= amount <= 10**4
